
  CREATE OR REPLACE EDITIONABLE PROCEDURE "KNRAMES"."SP_QLT14_S01" (
	P_TYPE           IN    varchar2, -- LIST, SUB_LIST, SUB_SAVE
	P_JSON_STR       IN    CLOB,
	P_SUCCESS       OUT    varchar2,
	P_RS_LIST       OUT    SYS_REFCURSOR
)
/*==============================================================================
 * PROGRAM ID    : QLT14{호출 프로그램 ID 기술}
 * PROGRAM NAME  : 품질검사(PS 점보롤 검사)이력조회{호출 프로그램 명 기술}
 * VERSION       : 1.0.0{최종 버전 기술}
 * DESCRIPTION   : 품질검사(PS 점보롤 검사)이력을 조회한다.{프로그램에 대한 상세한 내용 기술}
 *                 
 * AUTHOR NAME   : 김성하{최초 작성자 명 기술}
 * CREATE DATE   : 2022/05/15 {최초 작성일자 기술}
 * SYSTEM NAME   : MES
 * MAIN PROCEDURE: {주(상위) 프로시저 명칭 기술}  <생략가능>
 * SUB PROCEDURE : {아휘 프로시저 명칭 기술}      <생략가능>
 * SUB PACKAGES  : {하위 패키지 기술}            <생략가능>
 * OLD PROGRAM ID: {이전 시스템 프로그램 명 기술} <생략가능>
 * REVERSION HISTORY
 * ------------ ------- ------------- ------------------------------------------
 *    Date        Ver       Name          Description      
 * ------------ ------- ------------- ------------------------------------------
 * yyyy/mm/dd    1.0.0   김성하         Initial Version 
 *==============================================================================
 *  관련 테이블
 *       - [TB_MAS001] : (.R..) 자재 마스트                              
 *       - [TB_MAS015] : (.R..) 검사항목별 기준정보 등록 마스트                              
 *       - [TB_MAS016] : (.R..) 검사항목별 기준값 정보                                
 *       - [TB_Q20] : (.R..) 검사항목별 판정결과 등록 마스트                              
 *       - [TB_QLT021] : (.R..) 검사항목별 판정결과 정보
 *=============================================================================*/

AS

    V_PRG_NM          VARCHAR2(100)  := 'SP_QLT14_S01';     -- PROCEDURE NAME

    -- 오라클 에러 처리용 변수선언 영역
    E_EXCEPTION_USER  EXCEPTION;
    E_SQL_ERR_CD      NUMBER(5)           := 0;
    E_SQL_ERR_MSG     VARCHAR2(4000);


   -- V_RTN_CLOB       CLOB;
   -- V_RTN_CURSOR     SYS_REFCURSOR;
   -- V_ERROR          CLOB;


    -- JSON을 위한 변수선언 영역
    V_JSON           JSON_OBJECT_T;
    V_ARR_LIST       JSON_ARRAY_T;
    V_ARR_HEAD       JSON_ARRAY_T;
    V_OBJ            JSON_OBJECT_T;

    -- 세션값 처리용 변수선언 영역
    V_SQL            CLOB;
    V_SQL2           CLOB;

    V_RUN_SQL        varchar2(1);
    V_RANGE_SQL      varchar2(4000);
    V_DEBUG          varchar2(1);

    -- 세션값 처리용 변수선언 영역
    V_PLT_CD         varchar2(2);
    V_SESS_USER_ID   varchar2(20);

    -- 조건절 처리용 변수선언 영역
    V_WERKS            TB_MAS015.WERKS%TYPE; -- 플랜트코드
    V_MATNR            TB_MAS015.MATNR%TYPE; -- 자재코드
    V_MATNR_NM         TB_MAS001.MATNR_NM%TYPE; -- 자재명
    V_MATNR_GRP_CD     TB_MAS001.MATNR_GRP_CD%TYPE; -- 자재그룹
    V_INSP_YN          VARCHAR2(1);          -- 등록여부
    V_PCODE             TB_MAS001.PCODE%TYPE;   --지종코드
    V_BS_WGT            TB_MAS001.BS_WGT%TYPE;  --평량

    -- 리스트(그리드)의 값을 할당하기 위한 변수선언 영역        
    V_INSP_ITEM_GRP_CD TB_MAS015.INSP_ITEM_GRP_CD%TYPE; 
    V_INSP_ITEM_CD     TB_MAS016.INSP_ITEM_CD%TYPE;

    V_MACHINE            TB_WRK002.MACHINE%TYPE;
    V_ORDER_NO          TB_WRK002.ORDER_NO%TYPE;
    V_LOT_NO            TB_WRK002.LOT_NO%TYPE;
    
    V_MSRM_DATE        TB_QLT020.MSRM_DATE%TYPE;
    V_PRC_SEQNO        TB_QLT020.PRC_SEQNO%TYPE;

    V_MSRM_DT          VARCHAR2(20) := '';
    V_SDATE            VARCHAR2(30);
    V_EDATE            VARCHAR2(30);
    V_MSRM_ID          TB_QLT020.MSRM_ID%TYPE;
    V_SMPL_AMT         TB_QLT020.SMPL_AMT%TYPE;
    V_FNL_JDGM         TB_QLT020.FNL_JDGM%TYPE;
    V_IND_BCD          TB_QLT020.IND_BCD%TYPE;
    V_VGBEL            TB_QLT020.VGBEL%TYPE;
    V_VGPOS            TB_QLT020.VGPOS%TYPE;
    V_REQ_DIV          TB_QLT020.REQ_DIV%TYPE; 

    V_RST_VAL          TB_QLT021.RST_VAL%TYPE;
    V_RST_SEL          TB_QLT021.RST_SEL%TYPE;
    V_RST_TXT          TB_QLT021.RST_TXT%TYPE;
    V_RMK              TB_QLT021.RMK%TYPE;
    V_FIT_YN           TB_QLT021.FIT_YN%TYPE;
    V_INSP_REP_YN      TB_QLT021.INSP_REP_YN%TYPE;
    V_UUID             TB_QLT021.UUID%TYPE;

    --기타처리
    V_CREATE_FLG       CHAR(1)  := 'N';
    V_UPDATE_FLG       CHAR(1)  := 'N';    
    V_Q21_CNT         NUMBER   := 0;
    V_CHG_ACC          NUMBER   := 0;

BEGIN
   	OPEN P_RS_LIST FOR 
   	SELECT NULL FROM DUAL WHERE ROWNUM = 0;

   	V_DEBUG := 'N';
   	V_RUN_SQL := 'Y';

   	V_JSON := JSON_OBJECT_T.parse(P_JSON_STR);

   	V_SESS_USER_ID       :=     V_JSON.get_string('SES_USER_ID');
   	V_PLT_CD             :=     V_JSON.get_string('SES_WAREKY');

   	/* 조건값 할당 */
   	V_RANGE_SQL          :=		V_JSON.get_string('RANGE_SQL');
	
	V_WERKS              :=     V_JSON.get_string('WERKS');     			--플랜트코드
   	V_MACHINE            :=     V_JSON.get_string('MACHINE');   			--생산호기
   	V_ORDER_NO           :=     V_JSON.get_string('ORDER_NO');     		    --오더번호 
   	V_LOT_NO             :=     V_JSON.get_string('LOT_NO');   			    --LOT번호
   	
    /* 2022-09-14(수요일) 안상현, 필요없는 변수 제거
   	V_WERKS              :=       V_JSON.get_string('WERKS');     			--플랜트코드
   	V_MATNR_NM           :=       V_JSON.get_string('MATNR_NM');     		--자재명 
   	V_INSP_YN            :=       V_JSON.get_string('INSP_YN');   			--검사여부
   	V_INSP_ITEM_GRP_CD   :=       V_JSON.get_string('INSP_ITEM_GRP_CD'); 	--검사항목그룹
   	V_MATNR              :=       V_JSON.get_string('MATNR');     			--자재코드
   	V_MACHINE            :=       V_JSON.get_string('MACHINE');   			--생산호기
   	V_SDATE              :=       V_JSON.get_string('SDATE');     			--측정일시(시작)
   	V_EDATE              :=       V_JSON.get_string('EDATE');     			--측정일시(끝)
	*/
	IF P_TYPE = 'LIST' THEN /*상단 조회 리스트*/
   
		V_SQL := 'SELECT  Q20.INSP_ITEM_GRP_CD 	AS INSP_ITEM_GRP_CD		--검사항목그룹코드
			,Q20.WERKS          		AS WERKS        		--플랜트
            ,WRK002.ORDER_NO        AS ORDER_NO             --오더번호
			,Q20.LOT_NO        		AS LOT_NO       		--로트번호
			,Q20.IND_BCD        		AS IND_BCD      		--개별바코드
			,WRK002.WRK_CLASS  		AS WRK_CLASS			--반
			,MAS001.PCODE			AS PCODE      			--지종코드
			,MAS001.PCODE_NM   		AS PCODE_NM				--지종명
			,MAS001.BS_WGT     		AS BS_WGT				--평량
			,SCH006.PRDTYPE    		AS PRDTYPE				--생산라인구분
			,SCH006.PRDTYPETXT 		AS PRDTYPETXT			--생산라인구분명
			,WRK002.MACHINE    		AS MACHINE				--생산호기
			,SUBSTR(WRK002.MACHINE,3,2) || ''호기''		AS MACHINETXT			--생산호기명
			,WRK002.RSPEED     		AS RSPEED				--선속
			,WRK002.PRFM_DT 			AS PRFM_DT 				--실적일자
			,WRK002.PRD_DT  			AS PRD_DT  				--생산일자
			,TO_CHAR(WRK002.PRD_STR_DATE,''HH24MISS'') 	AS STR_TM        		--시작시간
			,TO_CHAR(WRK002.PRD_END_DATE,''HH24MISS'') 	AS END_TM        		--종료시간
			,WRK002.TM               AS TM					--생산시간(분)
			,WRK002.ROLLCNT          AS JROLLCNT      		--J/R권치수(M)
            , ''M''                  AS ROLLUNIT            --권치수단위
			,WRK002.WGT          	AS WGT					--중량
            , ''KG''                AS WUNIT                --중량단위
            ,(SELECT LISTAGG(Q21.RMK, '','') FROM TB_QLT021 Q21 
                  WHERE Q21.INSP_ITEM_GRP_CD = Q20.INSP_ITEM_GRP_CD AND Q21.MATNR = Q20.MATNR  AND Q21.WERKS = Q20.WERKS AND Q21.MSRM_DATE = Q20.MSRM_DATE 
                  GROUP BY Q21.INSP_ITEM_GRP_CD, Q21.MATNR, Q21.WERKS, Q21.MSRM_DATE ) AS ORDER_RMK
			,Q20.MSRM_DATE      		AS MSRM_DATE    		--측정일시
			,Q20.PRC_SEQNO      		AS PRC_SEQNO    		--처리순번
			,Q20.MATNR          		AS MATNR        		--자재코드
			,MAS001.MATNR_NM       	AS MATNR_NM				--자재명
			,SCH006.ROUTE            AS ROUTE				--항차
			,WRK002.UNIT				AS UNIT					--단위코드
			,FN_CD_VAL(''UNIT'',WRK002.UNIT)	AS UNIT_NM		--단위(명)
			,Q20.UCFMTY_AMT     		AS UCFMTY_AMT   		--부적합량
			,WRK002.REGID          	AS REGID        		--등록자ID 
			,FN_CD_VAL(''FNL_JDGM'',Q20.FNL_JDGM)							AS FNL_JDGM_NM	--최종판정(명)
			,(SELECT NMLAST FROM USRMA WHERE USRMA.USERID = Q20.MSRM_ID) 	AS MSRM_NM		--검사자
			,(SELECT NMLAST FROM USRMA WHERE USRMA.USERID = WRK002.REGID) 	AS REGNM		--등록자
		 	, (SELECT DECODE(M14.INPT_TYP, ''N'', Q21.RST_VAL, ''A'', Q21.RST_SEL, ''S'', Q21.RST_TXT, NULL)  FROM TB_QLT021 Q21, TB_MAS014 M14 WHERE Q21.INSP_ITEM_GRP_CD = M14.INSP_ITEM_GRP_CD(+) AND Q21.INSP_ITEM_CD = M14.INSP_ITEM_CD(+) AND Q21.INSP_ITEM_GRP_CD = Q20.INSP_ITEM_GRP_CD AND Q21.MATNR = Q20.MATNR AND Q21.WERKS = Q20.WERKS AND Q21.MSRM_DATE = Q20.MSRM_DATE AND  Q21.PRC_SEQNO = Q20.PRC_SEQNO AND Q21.INSP_ITEM_CD  = ''P1P01'')  AS CLASS_LEVEL3_1    --평량(전측)
			, (SELECT DECODE(M14.INPT_TYP, ''N'', Q21.RST_VAL, ''A'', Q21.RST_SEL, ''S'', Q21.RST_TXT, NULL)  FROM TB_QLT021 Q21, TB_MAS014 M14 WHERE Q21.INSP_ITEM_GRP_CD = M14.INSP_ITEM_GRP_CD(+) AND Q21.INSP_ITEM_CD = M14.INSP_ITEM_CD(+) AND Q21.INSP_ITEM_GRP_CD = Q20.INSP_ITEM_GRP_CD AND Q21.MATNR = Q20.MATNR AND Q21.WERKS = Q20.WERKS AND Q21.MSRM_DATE = Q20.MSRM_DATE AND  Q21.PRC_SEQNO = Q20.PRC_SEQNO AND Q21.INSP_ITEM_CD  = ''P1P02'')  AS CLASS_LEVEL3_2    --평량(중측)
			, (SELECT DECODE(M14.INPT_TYP, ''N'', Q21.RST_VAL, ''A'', Q21.RST_SEL, ''S'', Q21.RST_TXT, NULL)  FROM TB_QLT021 Q21, TB_MAS014 M14 WHERE Q21.INSP_ITEM_GRP_CD = M14.INSP_ITEM_GRP_CD(+) AND Q21.INSP_ITEM_CD = M14.INSP_ITEM_CD(+) AND Q21.INSP_ITEM_GRP_CD = Q20.INSP_ITEM_GRP_CD AND Q21.MATNR = Q20.MATNR AND Q21.WERKS = Q20.WERKS AND Q21.MSRM_DATE = Q20.MSRM_DATE AND  Q21.PRC_SEQNO = Q20.PRC_SEQNO AND Q21.INSP_ITEM_CD  = ''P1P03'')  AS CLASS_LEVEL3_3    --평량(후측)
			, (SELECT DECODE(M14.INPT_TYP, ''N'', Q21.RST_VAL, ''A'', Q21.RST_SEL, ''S'', Q21.RST_TXT, NULL)  FROM TB_QLT021 Q21, TB_MAS014 M14 WHERE Q21.INSP_ITEM_GRP_CD = M14.INSP_ITEM_GRP_CD(+) AND Q21.INSP_ITEM_CD = M14.INSP_ITEM_CD(+) AND Q21.INSP_ITEM_GRP_CD = Q20.INSP_ITEM_GRP_CD AND Q21.MATNR = Q20.MATNR AND Q21.WERKS = Q20.WERKS AND Q21.MSRM_DATE = Q20.MSRM_DATE AND  Q21.PRC_SEQNO = Q20.PRC_SEQNO AND Q21.INSP_ITEM_CD  = ''P1P04'')  AS CLASS_LEVEL3_4    --평량(평균)
 			, (SELECT DECODE(M14.INPT_TYP, ''N'', Q21.RST_VAL, ''A'', Q21.RST_SEL, ''S'', Q21.RST_TXT, NULL)  FROM TB_QLT021 Q21, TB_MAS014 M14 WHERE Q21.INSP_ITEM_GRP_CD = M14.INSP_ITEM_GRP_CD(+) AND Q21.INSP_ITEM_CD = M14.INSP_ITEM_CD(+) AND Q21.INSP_ITEM_GRP_CD = Q20.INSP_ITEM_GRP_CD AND Q21.MATNR = Q20.MATNR AND Q21.WERKS = Q20.WERKS AND Q21.MSRM_DATE = Q20.MSRM_DATE AND  Q21.PRC_SEQNO = Q20.PRC_SEQNO AND Q21.INSP_ITEM_CD  = ''P1P05'')  AS CLASS_LEVEL3_5    --두께(전측)
			, (SELECT DECODE(M14.INPT_TYP, ''N'', Q21.RST_VAL, ''A'', Q21.RST_SEL, ''S'', Q21.RST_TXT, NULL)  FROM TB_QLT021 Q21, TB_MAS014 M14 WHERE Q21.INSP_ITEM_GRP_CD = M14.INSP_ITEM_GRP_CD(+) AND Q21.INSP_ITEM_CD = M14.INSP_ITEM_CD(+) AND Q21.INSP_ITEM_GRP_CD = Q20.INSP_ITEM_GRP_CD AND Q21.MATNR = Q20.MATNR AND Q21.WERKS = Q20.WERKS AND Q21.MSRM_DATE = Q20.MSRM_DATE AND  Q21.PRC_SEQNO = Q20.PRC_SEQNO AND Q21.INSP_ITEM_CD  = ''P1P06'')  AS CLASS_LEVEL3_6    --두께(중측)
			, (SELECT DECODE(M14.INPT_TYP, ''N'', Q21.RST_VAL, ''A'', Q21.RST_SEL, ''S'', Q21.RST_TXT, NULL)  FROM TB_QLT021 Q21, TB_MAS014 M14 WHERE Q21.INSP_ITEM_GRP_CD = M14.INSP_ITEM_GRP_CD(+) AND Q21.INSP_ITEM_CD = M14.INSP_ITEM_CD(+) AND Q21.INSP_ITEM_GRP_CD = Q20.INSP_ITEM_GRP_CD AND Q21.MATNR = Q20.MATNR AND Q21.WERKS = Q20.WERKS AND Q21.MSRM_DATE = Q20.MSRM_DATE AND  Q21.PRC_SEQNO = Q20.PRC_SEQNO AND Q21.INSP_ITEM_CD  = ''P1P07'')  AS CLASS_LEVEL3_7    --두께(후측)
			, (SELECT DECODE(M14.INPT_TYP, ''N'', Q21.RST_VAL, ''A'', Q21.RST_SEL, ''S'', Q21.RST_TXT, NULL)  FROM TB_QLT021 Q21, TB_MAS014 M14 WHERE Q21.INSP_ITEM_GRP_CD = M14.INSP_ITEM_GRP_CD(+) AND Q21.INSP_ITEM_CD = M14.INSP_ITEM_CD(+) AND Q21.INSP_ITEM_GRP_CD = Q20.INSP_ITEM_GRP_CD AND Q21.MATNR = Q20.MATNR AND Q21.WERKS = Q20.WERKS AND Q21.MSRM_DATE = Q20.MSRM_DATE AND  Q21.PRC_SEQNO = Q20.PRC_SEQNO AND Q21.INSP_ITEM_CD  = ''P1P08'')  AS CLASS_LEVEL3_8    --두께(평균)
 			, (SELECT DECODE(M14.INPT_TYP, ''N'', Q21.RST_VAL, ''A'', Q21.RST_SEL, ''S'', Q21.RST_TXT, NULL)  FROM TB_QLT021 Q21, TB_MAS014 M14 WHERE Q21.INSP_ITEM_GRP_CD = M14.INSP_ITEM_GRP_CD(+) AND Q21.INSP_ITEM_CD = M14.INSP_ITEM_CD(+) AND Q21.INSP_ITEM_GRP_CD = Q20.INSP_ITEM_GRP_CD AND Q21.MATNR = Q20.MATNR AND Q21.WERKS = Q20.WERKS AND Q21.MSRM_DATE = Q20.MSRM_DATE AND  Q21.PRC_SEQNO = Q20.PRC_SEQNO AND Q21.INSP_ITEM_CD  = ''P1P09'')  AS CLASS_LEVEL2_3    --밀도
 			, (SELECT DECODE(M14.INPT_TYP, ''N'', Q21.RST_VAL, ''A'', Q21.RST_SEL, ''S'', Q21.RST_TXT, NULL)  FROM TB_QLT021 Q21, TB_MAS014 M14 WHERE Q21.INSP_ITEM_GRP_CD = M14.INSP_ITEM_GRP_CD(+) AND Q21.INSP_ITEM_CD = M14.INSP_ITEM_CD(+) AND Q21.INSP_ITEM_GRP_CD = Q20.INSP_ITEM_GRP_CD AND Q21.MATNR = Q20.MATNR AND Q21.WERKS = Q20.WERKS AND Q21.MSRM_DATE = Q20.MSRM_DATE AND  Q21.PRC_SEQNO = Q20.PRC_SEQNO AND Q21.INSP_ITEM_CD  = ''P1P10'')  AS CLASS_LEVEL3_9    --수분(전측)
			, (SELECT DECODE(M14.INPT_TYP, ''N'', Q21.RST_VAL, ''A'', Q21.RST_SEL, ''S'', Q21.RST_TXT, NULL)  FROM TB_QLT021 Q21, TB_MAS014 M14 WHERE Q21.INSP_ITEM_GRP_CD = M14.INSP_ITEM_GRP_CD(+) AND Q21.INSP_ITEM_CD = M14.INSP_ITEM_CD(+) AND Q21.INSP_ITEM_GRP_CD = Q20.INSP_ITEM_GRP_CD AND Q21.MATNR = Q20.MATNR AND Q21.WERKS = Q20.WERKS AND Q21.MSRM_DATE = Q20.MSRM_DATE AND  Q21.PRC_SEQNO = Q20.PRC_SEQNO AND Q21.INSP_ITEM_CD  = ''P1P11'')  AS CLASS_LEVEL3_10   --수분(중측)
			, (SELECT DECODE(M14.INPT_TYP, ''N'', Q21.RST_VAL, ''A'', Q21.RST_SEL, ''S'', Q21.RST_TXT, NULL)  FROM TB_QLT021 Q21, TB_MAS014 M14 WHERE Q21.INSP_ITEM_GRP_CD = M14.INSP_ITEM_GRP_CD(+) AND Q21.INSP_ITEM_CD = M14.INSP_ITEM_CD(+) AND Q21.INSP_ITEM_GRP_CD = Q20.INSP_ITEM_GRP_CD AND Q21.MATNR = Q20.MATNR AND Q21.WERKS = Q20.WERKS AND Q21.MSRM_DATE = Q20.MSRM_DATE AND  Q21.PRC_SEQNO = Q20.PRC_SEQNO AND Q21.INSP_ITEM_CD  = ''P1P12'')  AS CLASS_LEVEL3_11   --수분(후측)
			, (SELECT DECODE(M14.INPT_TYP, ''N'', Q21.RST_VAL, ''A'', Q21.RST_SEL, ''S'', Q21.RST_TXT, NULL)  FROM TB_QLT021 Q21, TB_MAS014 M14 WHERE Q21.INSP_ITEM_GRP_CD = M14.INSP_ITEM_GRP_CD(+) AND Q21.INSP_ITEM_CD = M14.INSP_ITEM_CD(+) AND Q21.INSP_ITEM_GRP_CD = Q20.INSP_ITEM_GRP_CD AND Q21.MATNR = Q20.MATNR AND Q21.WERKS = Q20.WERKS AND Q21.MSRM_DATE = Q20.MSRM_DATE AND  Q21.PRC_SEQNO = Q20.PRC_SEQNO AND Q21.INSP_ITEM_CD  = ''P1P13'')  AS CLASS_LEVEL3_12   --수분(평균)
 			, (SELECT DECODE(M14.INPT_TYP, ''N'', Q21.RST_VAL, ''A'', Q21.RST_SEL, ''S'', Q21.RST_TXT, NULL)  FROM TB_QLT021 Q21, TB_MAS014 M14 WHERE Q21.INSP_ITEM_GRP_CD = M14.INSP_ITEM_GRP_CD(+) AND Q21.INSP_ITEM_CD = M14.INSP_ITEM_CD(+) AND Q21.INSP_ITEM_GRP_CD = Q20.INSP_ITEM_GRP_CD AND Q21.MATNR = Q20.MATNR AND Q21.WERKS = Q20.WERKS AND Q21.MSRM_DATE = Q20.MSRM_DATE AND  Q21.PRC_SEQNO = Q20.PRC_SEQNO AND Q21.INSP_ITEM_CD  = ''P1P14'')  AS CLASS_LEVEL3_13   --표면 백색도(전측)
			, (SELECT DECODE(M14.INPT_TYP, ''N'', Q21.RST_VAL, ''A'', Q21.RST_SEL, ''S'', Q21.RST_TXT, NULL)  FROM TB_QLT021 Q21, TB_MAS014 M14 WHERE Q21.INSP_ITEM_GRP_CD = M14.INSP_ITEM_GRP_CD(+) AND Q21.INSP_ITEM_CD = M14.INSP_ITEM_CD(+) AND Q21.INSP_ITEM_GRP_CD = Q20.INSP_ITEM_GRP_CD AND Q21.MATNR = Q20.MATNR AND Q21.WERKS = Q20.WERKS AND Q21.MSRM_DATE = Q20.MSRM_DATE AND  Q21.PRC_SEQNO = Q20.PRC_SEQNO AND Q21.INSP_ITEM_CD  = ''P1P15'')  AS CLASS_LEVEL3_14   --표면 백색도(중측)
