			, (SELECT DECODE(M14.INPT_TYP, ''N'', Q21.RST_VAL, ''A'', Q21.RST_SEL, ''S'', Q21.RST_TXT, NULL)  FROM TB_QLT021 Q21, TB_MAS014 M14 WHERE Q21.INSP_ITEM_GRP_CD = M14.INSP_ITEM_GRP_CD(+) AND Q21.INSP_ITEM_CD = M14.INSP_ITEM_CD(+) AND Q21.INSP_ITEM_GRP_CD = Q20.INSP_ITEM_GRP_CD AND Q21.MATNR = Q20.MATNR AND Q21.WERKS = Q20.WERKS AND Q21.MSRM_DATE = Q20.MSRM_DATE AND  Q21.PRC_SEQNO = Q20.PRC_SEQNO AND Q21.INSP_ITEM_CD  = ''P1P80'')  AS CLASS_LEVEL2_40   --금속검출기 20장(CD)
			, (SELECT DECODE(M14.INPT_TYP, ''N'', TO_CHAR(Q21.RST_VAL,''9990.00''), ''A'', Q21.RST_SEL, ''S'', Q21.RST_TXT, NULL)  FROM TB_QLT021 Q21, TB_MAS014 M14 WHERE Q21.INSP_ITEM_GRP_CD = M14.INSP_ITEM_GRP_CD(+) AND Q21.INSP_ITEM_CD = M14.INSP_ITEM_CD(+) AND Q21.INSP_ITEM_GRP_CD = Q20.INSP_ITEM_GRP_CD AND Q21.MATNR = Q20.MATNR AND Q21.WERKS = Q20.WERKS AND Q21.MSRM_DATE = Q20.MSRM_DATE AND  Q21.PRC_SEQNO = Q20.PRC_SEQNO AND Q21.INSP_ITEM_CD  = ''P1P81'')  AS CLASS_LEVEL3_59   --S/P 농도
			, (SELECT DECODE(M14.INPT_TYP, ''N'', TO_CHAR(Q21.RST_VAL,''9990.00''), ''A'', Q21.RST_SEL, ''S'', Q21.RST_TXT, NULL)  FROM TB_QLT021 Q21, TB_MAS014 M14 WHERE Q21.INSP_ITEM_GRP_CD = M14.INSP_ITEM_GRP_CD(+) AND Q21.INSP_ITEM_CD = M14.INSP_ITEM_CD(+) AND Q21.INSP_ITEM_GRP_CD = Q20.INSP_ITEM_GRP_CD AND Q21.MATNR = Q20.MATNR AND Q21.WERKS = Q20.WERKS AND Q21.MSRM_DATE = Q20.MSRM_DATE AND  Q21.PRC_SEQNO = Q20.PRC_SEQNO AND Q21.INSP_ITEM_CD  = ''P1P82'')  AS CLASS_LEVEL3_60   --B/C 농도
			, (SELECT DECODE(M14.INPT_TYP, ''N'', TO_CHAR(Q21.RST_VAL,''9990.00''), ''A'', Q21.RST_SEL, ''S'', Q21.RST_TXT, NULL)  FROM TB_QLT021 Q21, TB_MAS014 M14 WHERE Q21.INSP_ITEM_GRP_CD = M14.INSP_ITEM_GRP_CD(+) AND Q21.INSP_ITEM_CD = M14.INSP_ITEM_CD(+) AND Q21.INSP_ITEM_GRP_CD = Q20.INSP_ITEM_GRP_CD AND Q21.MATNR = Q20.MATNR AND Q21.WERKS = Q20.WERKS AND Q21.MSRM_DATE = Q20.MSRM_DATE AND  Q21.PRC_SEQNO = Q20.PRC_SEQNO AND Q21.INSP_ITEM_CD  = ''P1P83'')  AS CLASS_LEVEL3_61   --전분/코팅 농도
			, (SELECT DECODE(M14.INPT_TYP, ''N'', TO_CHAR(Q21.RST_VAL,''9990.00''), ''A'', Q21.RST_SEL, ''S'', Q21.RST_TXT, NULL)  FROM TB_QLT021 Q21, TB_MAS014 M14 WHERE Q21.INSP_ITEM_GRP_CD = M14.INSP_ITEM_GRP_CD(+) AND Q21.INSP_ITEM_CD = M14.INSP_ITEM_CD(+) AND Q21.INSP_ITEM_GRP_CD = Q20.INSP_ITEM_GRP_CD AND Q21.MATNR = Q20.MATNR AND Q21.WERKS = Q20.WERKS AND Q21.MSRM_DATE = Q20.MSRM_DATE AND  Q21.PRC_SEQNO = Q20.PRC_SEQNO AND Q21.INSP_ITEM_CD  = ''P1P84'')  AS CLASS_LEVEL3_62   --표면 배합
			, (SELECT DECODE(M14.INPT_TYP, ''N'', TO_CHAR(Q21.RST_VAL,''9990.00''), ''A'', Q21.RST_SEL, ''S'', Q21.RST_TXT, NULL)  FROM TB_QLT021 Q21, TB_MAS014 M14 WHERE Q21.INSP_ITEM_GRP_CD = M14.INSP_ITEM_GRP_CD(+) AND Q21.INSP_ITEM_CD = M14.INSP_ITEM_CD(+) AND Q21.INSP_ITEM_GRP_CD = Q20.INSP_ITEM_GRP_CD AND Q21.MATNR = Q20.MATNR AND Q21.WERKS = Q20.WERKS AND Q21.MSRM_DATE = Q20.MSRM_DATE AND  Q21.PRC_SEQNO = Q20.PRC_SEQNO AND Q21.INSP_ITEM_CD  = ''P1P85'')  AS CLASS_LEVEL3_63   --표이면 배합
			, (SELECT DECODE(M14.INPT_TYP, ''N'', TO_CHAR(Q21.RST_VAL,''9990.00''), ''A'', Q21.RST_SEL, ''S'', Q21.RST_TXT, NULL)  FROM TB_QLT021 Q21, TB_MAS014 M14 WHERE Q21.INSP_ITEM_GRP_CD = M14.INSP_ITEM_GRP_CD(+) AND Q21.INSP_ITEM_CD = M14.INSP_ITEM_CD(+) AND Q21.INSP_ITEM_GRP_CD = Q20.INSP_ITEM_GRP_CD AND Q21.MATNR = Q20.MATNR AND Q21.WERKS = Q20.WERKS AND Q21.MSRM_DATE = Q20.MSRM_DATE AND  Q21.PRC_SEQNO = Q20.PRC_SEQNO AND Q21.INSP_ITEM_CD  = ''P1P86'')  AS CLASS_LEVEL3_64   --심면 배합
			, (SELECT DECODE(M14.INPT_TYP, ''N'', TO_CHAR(Q21.RST_VAL,''9990.00''), ''A'', Q21.RST_SEL, ''S'', Q21.RST_TXT, NULL)  FROM TB_QLT021 Q21, TB_MAS014 M14 WHERE Q21.INSP_ITEM_GRP_CD = M14.INSP_ITEM_GRP_CD(+) AND Q21.INSP_ITEM_CD = M14.INSP_ITEM_CD(+) AND Q21.INSP_ITEM_GRP_CD = Q20.INSP_ITEM_GRP_CD AND Q21.MATNR = Q20.MATNR AND Q21.WERKS = Q20.WERKS AND Q21.MSRM_DATE = Q20.MSRM_DATE AND  Q21.PRC_SEQNO = Q20.PRC_SEQNO AND Q21.INSP_ITEM_CD  = ''P1P87'')  AS CLASS_LEVEL3_65   --후이면 배합
			, (SELECT DECODE(M14.INPT_TYP, ''N'', TO_CHAR(Q21.RST_VAL,''9990.00''), ''A'', Q21.RST_SEL, ''S'', Q21.RST_TXT, NULL)  FROM TB_QLT021 Q21, TB_MAS014 M14 WHERE Q21.INSP_ITEM_GRP_CD = M14.INSP_ITEM_GRP_CD(+) AND Q21.INSP_ITEM_CD = M14.INSP_ITEM_CD(+) AND Q21.INSP_ITEM_GRP_CD = Q20.INSP_ITEM_GRP_CD AND Q21.MATNR = Q20.MATNR AND Q21.WERKS = Q20.WERKS AND Q21.MSRM_DATE = Q20.MSRM_DATE AND  Q21.PRC_SEQNO = Q20.PRC_SEQNO AND Q21.INSP_ITEM_CD  = ''P1P88'')  AS CLASS_LEVEL3_66   --후면 배합
			, (SELECT DECODE(M14.INPT_TYP, ''N'', Q21.RST_VAL, ''A'', Q21.RST_SEL, ''S'', Q21.RST_TXT, NULL)  FROM TB_QLT021 Q21, TB_MAS014 M14 WHERE Q21.INSP_ITEM_GRP_CD = M14.INSP_ITEM_GRP_CD(+) AND Q21.INSP_ITEM_CD = M14.INSP_ITEM_CD(+) AND Q21.INSP_ITEM_GRP_CD = Q20.INSP_ITEM_GRP_CD AND Q21.MATNR = Q20.MATNR AND Q21.WERKS = Q20.WERKS AND Q21.MSRM_DATE = Q20.MSRM_DATE AND  Q21.PRC_SEQNO = Q20.PRC_SEQNO AND Q21.INSP_ITEM_CD  = ''P1P89'')  AS CLASS_LEVEL3_67   --목분 유량
			, (SELECT DECODE(M14.INPT_TYP, ''N'', Q21.RST_VAL, ''A'', Q21.RST_SEL, ''S'', Q21.RST_TXT, NULL)  FROM TB_QLT021 Q21, TB_MAS014 M14 WHERE Q21.INSP_ITEM_GRP_CD = M14.INSP_ITEM_GRP_CD(+) AND Q21.INSP_ITEM_CD = M14.INSP_ITEM_CD(+) AND Q21.INSP_ITEM_GRP_CD = Q20.INSP_ITEM_GRP_CD AND Q21.MATNR = Q20.MATNR AND Q21.WERKS = Q20.WERKS AND Q21.MSRM_DATE = Q20.MSRM_DATE AND  Q21.PRC_SEQNO = Q20.PRC_SEQNO AND Q21.INSP_ITEM_CD  = ''P1P90'')  AS CLASS_LEVEL3_68   --표면 유량
			, (SELECT DECODE(M14.INPT_TYP, ''N'', Q21.RST_VAL, ''A'', Q21.RST_SEL, ''S'', Q21.RST_TXT, NULL)  FROM TB_QLT021 Q21, TB_MAS014 M14 WHERE Q21.INSP_ITEM_GRP_CD = M14.INSP_ITEM_GRP_CD(+) AND Q21.INSP_ITEM_CD = M14.INSP_ITEM_CD(+) AND Q21.INSP_ITEM_GRP_CD = Q20.INSP_ITEM_GRP_CD AND Q21.MATNR = Q20.MATNR AND Q21.WERKS = Q20.WERKS AND Q21.MSRM_DATE = Q20.MSRM_DATE AND  Q21.PRC_SEQNO = Q20.PRC_SEQNO AND Q21.INSP_ITEM_CD  = ''P1P91'')  AS CLASS_LEVEL3_69   --표이면 유량
			, (SELECT DECODE(M14.INPT_TYP, ''N'', Q21.RST_VAL, ''A'', Q21.RST_SEL, ''S'', Q21.RST_TXT, NULL)  FROM TB_QLT021 Q21, TB_MAS014 M14 WHERE Q21.INSP_ITEM_GRP_CD = M14.INSP_ITEM_GRP_CD(+) AND Q21.INSP_ITEM_CD = M14.INSP_ITEM_CD(+) AND Q21.INSP_ITEM_GRP_CD = Q20.INSP_ITEM_GRP_CD AND Q21.MATNR = Q20.MATNR AND Q21.WERKS = Q20.WERKS AND Q21.MSRM_DATE = Q20.MSRM_DATE AND  Q21.PRC_SEQNO = Q20.PRC_SEQNO AND Q21.INSP_ITEM_CD  = ''P1P92'')  AS CLASS_LEVEL3_70   --후이면 유량
			, (SELECT DECODE(M14.INPT_TYP, ''N'', Q21.RST_VAL, ''A'', Q21.RST_SEL, ''S'', Q21.RST_TXT, NULL)  FROM TB_QLT021 Q21, TB_MAS014 M14 WHERE Q21.INSP_ITEM_GRP_CD = M14.INSP_ITEM_GRP_CD(+) AND Q21.INSP_ITEM_CD = M14.INSP_ITEM_CD(+) AND Q21.INSP_ITEM_GRP_CD = Q20.INSP_ITEM_GRP_CD AND Q21.MATNR = Q20.MATNR AND Q21.WERKS = Q20.WERKS AND Q21.MSRM_DATE = Q20.MSRM_DATE AND  Q21.PRC_SEQNO = Q20.PRC_SEQNO AND Q21.INSP_ITEM_CD  = ''P1P93'')  AS CLASS_LEVEL3_71   --후면 유량
			, (SELECT DECODE(M14.INPT_TYP, ''N'', TO_CHAR(Q21.RST_VAL,''9990.00''), ''A'', Q21.RST_SEL, ''S'', Q21.RST_TXT, NULL)  FROM TB_QLT021 Q21, TB_MAS014 M14 WHERE Q21.INSP_ITEM_GRP_CD = M14.INSP_ITEM_GRP_CD(+) AND Q21.INSP_ITEM_CD = M14.INSP_ITEM_CD(+) AND Q21.INSP_ITEM_GRP_CD = Q20.INSP_ITEM_GRP_CD AND Q21.MATNR = Q20.MATNR AND Q21.WERKS = Q20.WERKS AND Q21.MSRM_DATE = Q20.MSRM_DATE AND  Q21.PRC_SEQNO = Q20.PRC_SEQNO AND Q21.INSP_ITEM_CD  = ''P1P94'')  AS CLASS_LEVEL2_43   --공정특이사항
			FROM 
				TB_QLT020 Q20
			LEFT JOIN TB_MAS001 MAS001 ON (MAS001.WERKS = Q20.WERKS AND MAS001.MATNR = Q20.MATNR)
			LEFT JOIN TB_WRK002 WRK002 ON (WRK002.WERKS = Q20.WERKS AND WRK002.MATNR = Q20.MATNR AND WRK002.LOT_NO = Q20.LOT_NO AND WRK002.IND_BCD = Q20.IND_BCD)
			LEFT JOIN TB_SCH006 SCH006 ON (SCH006.AUFNR = WRK002.ORDER_NO)
			WHERE 1=1
			AND Q20.INSP_ITEM_GRP_CD = ''P1'' ';
		
			--플랜트
			IF V_WERKS IS NOT NULL OR TRIM(V_WERKS) != '' THEN
	            V_SQL2 := V_SQL2 || ' AND Q20.WERKS  = ''' || V_WERKS || '''';             
	        END IF;
	
	       	--생산호기
	        IF V_MACHINE IS NOT NULL OR TRIM(V_MACHINE) != '' THEN 
	            V_SQL2 := V_SQL2 || ' AND WRK002.MACHINE  = ''' || V_MACHINE || '''';             
	        END IF;

--	       	--오더번호
--	        IF V_ORDER_NO IS NOT NULL OR TRIM(V_ORDER_NO) != '' THEN 
--	            V_SQL2 := V_SQL2 || ' AND WRK002.ORDER_NO  = ''' || V_ORDER_NO || '''';             
--	        END IF;

--	       	--LOT번호
--	        IF V_LOT_NO IS NOT NULL OR TRIM(V_LOT_NO) != '' THEN 
--	            V_SQL2 := V_SQL2 || ' AND WRK002.LOT_NO  LIKE ''' || V_LOT_NO || '%''';             
--	        END IF;
	       
	       	--지종코드, 평량, 검사일시
	       	IF V_RANGE_SQL IS NOT NULL OR TRIM(V_RANGE_SQL) != '' THEN -- 지종(M001.PCODE, 평량(M001.BS_WGT)
	            V_RANGE_SQL := REPLACE(V_RANGE_SQL, 'PRFM_DT',  'WRK002.PRFM_DT');
                V_RANGE_SQL := REPLACE(V_RANGE_SQL, 'ORDER_NO',  'WRK002.ORDER_NO');
                V_RANGE_SQL := REPLACE(V_RANGE_SQL, 'MACHINE',  'WRK002.MACHINE');
                V_RANGE_SQL := REPLACE(V_RANGE_SQL, 'MSRM_DATE', 'TO_CHAR(Q20.MSRM_DATE, ''YYYYMMDD'')' );
                
                V_SQL2 := V_SQL2 || V_RANGE_SQL;
	        END IF;
	
			V_SQL2 := V_SQL2 || ' ORDER BY Q20.IND_BCD';

            dbms_lob.append(V_SQL,V_SQL2);

-- INSERT INTO PROC_LOG(SQL_STR) VALUES (V_SQL);
  
        
        BEGIN           
     		OPEN P_RS_LIST FOR V_SQL;

        EXCEPTION           
        WHEN OTHERS THEN 
            P_SUCCESS           := 'N';
            E_SQL_ERR_CD        := -20000;
			E_SQL_ERR_MSG       := SQLCODE || ': EXCEPTION OTHER ERROR. [' || SUBSTR(SQLERRM,1,500) || ']';

            SP_PROC_ERROR(V_PLT_CD, V_PRG_NM, E_SQL_ERR_CD, E_SQL_ERR_MSG, V_SESS_USER_ID);

            RAISE_APPLICATION_ERROR(E_SQL_ERR_CD, E_SQL_ERR_MSG);           
            RETURN;           
        END;    


    ELSIF P_TYPE = 'SUB_LIST' THEN  /* 하단 상세 조회 리스트*/
          RETURN; 

    ELSIF P_TYPE = 'SAVE' THEN
          RETURN;            

    ELSIF P_TYPE = 'SUB_SAVE' THEN
          RETURN;

    END IF;

    P_SUCCESS := 'Y';

    COMMIT;

    EXCEPTION
    WHEN E_EXCEPTION_USER THEN

        -- 에러 내역 SET
	    P_SUCCESS           := 'N';
        E_SQL_ERR_CD        := -20000;
		E_SQL_ERR_MSG       := SQLCODE || ': EXCEPTION OTHER ERROR. [' || SUBSTR(SQLERRM,1,500) || ']';
 --       SP_PROC_ERROR(V_PLT_CD, V_PRG_NM, E_SQL_ERR_CD, V_SQL||E_SQL_ERR_MSG, V_SESS_USER_ID);

        ROLLBACK;
        RAISE_APPLICATION_ERROR(E_SQL_ERR_CD, E_SQL_ERR_MSG);

    WHEN OTHERS THEN
	    P_SUCCESS           := 'N';
        E_SQL_ERR_CD        := -20000;
		E_SQL_ERR_MSG       := SQLCODE || ': EXCEPTION OTHER ERROR. [' || SUBSTR(SQLERRM,1,500) || ']';
        SP_PROC_ERROR(V_PLT_CD, V_PRG_NM, E_SQL_ERR_CD, E_SQL_ERR_MSG, V_SESS_USER_ID);

        ROLLBACK;
        RAISE_APPLICATION_ERROR(E_SQL_ERR_CD, E_SQL_ERR_MSG);
END;
